/**
 * `release:prepare` orchestration — dry-run by default, never pushes/tags.
 *
 * Two-phase release identity (decisions §5):
 *
 *   P  version commit: package.json version + code, reviewed and merged. Its
 *      hash is already known (HEAD when the release tooling runs).
 *   R  release commit: child of P, generated by this tool with
 *      `platform-updates/release.json` (clientBuildCommit = P) and the rebuilt
 *      artifacts. R is the immutable install target referenced by the index.
 *
 * Dry-run performs every check, including two independent builds in throwaway
 * copies, and writes nothing. `--write` (maintainer-only, explicit) writes
 * release.json, rebuilds the working tree, then commits exactly
 * `platform-updates/release.json`, `client.js`, `games/**`, `registry/**` as R.
 * A failure before the commit rolls the worktree back; there is no push, no
 * tag, no release.
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import {
  ARTIFACT_ROOTS,
  RELEASE_IDENTITY_PATH,
  REPO_URL,
  releaseCommitMessage,
  RELEASE_COMMIT_RE,
} from './constants.mjs';
import { fail } from './errors.mjs';
import { collectArtifacts, compareInventories } from './fs-tree.mjs';
import { createGit, normalizeRepoUrl } from './git.mjs';
import { assertPackageFiles, assertReleasePackage, assertClientIdentity } from './package-manifest.mjs';
import {
  buildReleaseIdentity,
  isFullCommit,
  serializeReleaseIdentity,
} from './release-identity.mjs';
import { inspectReleaseCommit } from './release-commit.mjs';
import { runRepositoryBuild, verifyBuildDeterminism } from './determinism.mjs';
import { isValidVersion } from './semver.mjs';

function readPackageJson(root) {
  const file = path.join(root, 'package.json');
  let text;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch {
    fail('E_RELEASE_PACKAGE', 'missing package.json in the release worktree');
  }
  try {
    return JSON.parse(text);
  } catch (error) {
    fail('E_RELEASE_PACKAGE', `package.json is not valid JSON: ${error.message}`);
  }
}

function atomicWrite(file, text) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temp = `${file}.tmp-${String(process.pid)}`;
  fs.writeFileSync(temp, text, { mode: 0o644 });
  fs.renameSync(temp, file);
}

function snapshot(root, backupRoot) {
  const state = { artifacts: {}, identityExisted: false, platformUpdatesExisted: false };
  for (const relative of ARTIFACT_ROOTS) {
    const absolute = path.join(root, relative);
    if (!fs.existsSync(absolute)) continue;
    const target = path.join(backupRoot, relative);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.cpSync(absolute, target, { recursive: true });
    state.artifacts[relative] = true;
  }
  const identityPath = path.join(root, RELEASE_IDENTITY_PATH);
  state.identityExisted = fs.existsSync(identityPath);
  state.platformUpdatesExisted = fs.existsSync(path.dirname(identityPath));
  if (state.identityExisted) {
    const target = path.join(backupRoot, 'release-identity.json');
    fs.copyFileSync(identityPath, target);
  }
  return state;
}

function restore(root, backupRoot, state) {
  for (const relative of ARTIFACT_ROOTS) {
    const absolute = path.join(root, relative);
    fs.rmSync(absolute, { recursive: true, force: true });
    if (state.artifacts[relative]) {
      fs.cpSync(path.join(backupRoot, relative), absolute, { recursive: true });
    }
  }
  const identityPath = path.join(root, RELEASE_IDENTITY_PATH);
  if (state.identityExisted) {
    fs.copyFileSync(path.join(backupRoot, 'release-identity.json'), identityPath);
  } else {
    fs.rmSync(identityPath, { force: true });
    const directory = path.dirname(identityPath);
    if (!state.platformUpdatesExisted && fs.existsSync(directory)) {
      try {
        if (fs.readdirSync(directory).length === 0) fs.rmdirSync(directory);
      } catch {
        // best effort: a leftover empty platform-updates/ is untracked and visible to the maintainer
      }
    }
  }
}

/**
 * @param {object} options
 * @param {string} options.root repository worktree root
 * @param {string} [options.version] expected package.json version (asserted, never bumped here)
 * @param {boolean} [options.write] create the release commit (maintainer authorisation)
 * @param {Function} [options.runBuild] build runner seam for tests
 * @param {object} [options.git] pre-created git adapter (tests)
 * @returns {Promise<object>} structured result for the CLI
 */
export async function prepareRelease(options = {}) {
  const root = path.resolve(options.root || process.cwd());
  const write = options.write === true;
  const git = options.git || createGit({ cwd: root });
  const runBuild = options.runBuild || runRepositoryBuild;

  if (!git.isRepo()) {
    fail('E_RELEASE_NOT_GIT', `${root} is not a git worktree`, {
      guidance: 'run release:prepare from the repository worktree',
    });
  }
  const dirty = git.statusPorcelain();
  if (dirty.trim() !== '') {
    const files = dirty.split('\n').map((line) => line.trim()).filter(Boolean);
    fail('E_RELEASE_DIRTY', 'working tree is not clean', {
      guidance: 'commit or stash every change first: a release commit must contain only generated release identity + artifacts',
      details: { files: files.slice(0, 20), total: files.length },
    });
  }
  const branch = git.branch();
  if (!branch) {
    fail('E_RELEASE_DETACHED', 'HEAD is detached; release commits must be created on a branch', {
      guidance: 'check out the version commit on a branch before running release:prepare --write',
    });
  }

  const remote = git.remoteUrl('origin');
  const normalized = normalizeRepoUrl(remote);
  if (normalized !== REPO_URL) {
    fail('E_RELEASE_REPO_MISMATCH', `origin remote ${JSON.stringify(remote)} does not identify ${REPO_URL}`, {
      guidance: `this tooling only prepares releases for ${REPO_URL}; set origin to ${REPO_URL}.git`,
    });
  }

  const p = git.head();
  if (!isFullCommit(p)) {
    fail('E_RELEASE_BAD_COMMIT', `HEAD ${JSON.stringify(p)} is not a full 40-hex commit`);
  }
  const headSubject = git.commitSubject(p);
  if (RELEASE_COMMIT_RE.test(headSubject)) {
    fail('E_RELEASE_HEAD_IS_RELEASE', `HEAD is already a release commit (${headSubject})`, {
      guidance: 'make the code/version changes on a new version commit P first; release:prepare generates exactly one release commit per P',
    });
  }

  const pkg = readPackageJson(root);
  const version = options.version === undefined ? pkg.version : options.version;
  if (!isValidVersion(version)) {
    fail('E_RELEASE_VERSION_MISMATCH', `--version ${JSON.stringify(version)} is not an exact SemVer version`);
  }
  if (pkg.version !== version) {
    fail('E_RELEASE_VERSION_MISMATCH', `package.json declares ${JSON.stringify(pkg.version)}, expected ${JSON.stringify(version)}`, {
      guidance: `release:prepare never bumps the version: bump package.json to ${version} in a separate version commit P, merge it, then release from that clean commit`,
      details: { packageVersion: pkg.version, requested: version },
    });
  }
  assertReleasePackage(pkg, { where: `package.json@${p.slice(0, 12)}` });
  assertPackageFiles(pkg);
  if (!fs.existsSync(path.join(root, 'scripts', 'build.mjs'))) {
    fail('E_RELEASE_BUILD_FAILED', 'missing scripts/build.mjs', {
      guidance: 'release:prepare builds the shipped artifacts with the repository pipeline',
    });
  }

  const deterministic = verifyBuildDeterminism({ root, version, clientBuildCommit: p, runBuild });
  const identity = deterministic.identity;
  const identityText = serializeReleaseIdentity(identity);
  const message = releaseCommitMessage(version, p);
  const plannedPaths = [RELEASE_IDENTITY_PATH, ...ARTIFACT_ROOTS];

  const base = {
    ok: true,
    tool: 'release:prepare',
    mode: write ? 'write' : 'dry-run',
    root,
    branch,
    repo: REPO_URL,
    version,
    clientBuildCommit: p,
    deterministic: true,
    builds: deterministic.builds,
    clientIdentity: deterministic.clientIdentity,
    artifacts: {
      algorithm: identity.artifacts.algorithm,
      roots: identity.artifacts.roots,
      sha256: identity.artifacts.sha256,
      files: identity.artifacts.files,
      bytes: identity.artifacts.bytes,
    },
    identity,
    identityText,
    plannedPaths,
    commitMessage: message,
    commit: null,
  };

  if (!write) return base;

  // ---- --write: maintainer-authorised release commit creation ----
  const backupRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'dsh-release-backup-'));
  const state = snapshot(root, backupRoot);
  const identityPath = path.join(root, RELEASE_IDENTITY_PATH);
  let staged = false;
  let committed = false;
  let release = null;
  try {
    atomicWrite(identityPath, identityText);
    runBuild(root);

    const actual = collectArtifacts(root);
    const delta = compareInventories(deterministic.inventory, actual);
    if (!delta.equal) {
      fail('E_RELEASE_BUILD_MISMATCH', 'the working-tree build did not reproduce the deterministically verified artifacts', {
        guidance: 'the checked-in build must equal the two isolated builds; fix the build (timestamps/paths) and retry',
        details: { differences: delta },
      });
    }
    const clientText = fs.readFileSync(path.join(root, 'client.js'), 'utf8');
    assertClientIdentity(clientText, { version, clientBuildCommit: p, where: 'client.js@working-tree' });

    const expectedPaths = deterministic.inventory.files.map((file) => file.path);
    const committable = new Set(git.listCommittableFiles([...ARTIFACT_ROOTS, RELEASE_IDENTITY_PATH]));
    const uncommittable = expectedPaths.filter((relative) => !committable.has(relative));
    if (uncommittable.length > 0) {
      fail('E_RELEASE_ARTIFACT_IGNORED', 'some release artifacts are ignored by git and cannot be committed', {
        guidance: 'release artifacts must be tracked/non-ignored plain files; adjust .gitignore or the build',
        details: { files: uncommittable.slice(0, 20) },
      });
    }

    const statusPaths = git.asyncStatusPaths();
    const allowed = (relative) => relative === RELEASE_IDENTITY_PATH
      || ARTIFACT_ROOTS.some((rootDir) => relative === rootDir || relative.startsWith(`${rootDir}/`));
    const unexpected = statusPaths.filter((relative) => !allowed(relative));
    if (unexpected.length > 0) {
      fail('E_RELEASE_UNEXPECTED_CHANGES', 'the build/identity step touched files outside release.json + artifacts', {
        guidance: 'release:prepare --write must only change platform-updates/release.json, client.js, games/** and registry/**',
        details: { files: unexpected.slice(0, 20) },
      });
    }

    git.add([RELEASE_IDENTITY_PATH, ...ARTIFACT_ROOTS]);
    staged = true;
    git.commit(message);
    staged = false;
    committed = true;
    release = git.head();

    const inspection = inspectReleaseCommit({ git, release, version });
    if (inspection.buildCommit !== p) {
      fail('E_RELEASE_COMMIT_MISMATCH', 'release commit does not declare the expected build commit', {
        details: { release, expected: p, actual: inspection.buildCommit },
      });
    }
    const committedDelta = compareInventories(deterministic.inventory, inspection.inventory);
    if (!committedDelta.equal) {
      fail('E_RELEASE_COMMIT_MISMATCH', 'committed artifacts differ from the verified artifacts', {
        details: { release, differences: committedDelta },
      });
    }
    const leftover = git.statusPorcelain();
    if (leftover.trim() !== '') {
      fail('E_RELEASE_DIRTY_AFTER_COMMIT', 'release commit created but the working tree is not clean afterwards', {
        guidance: 'the release commit exists; inspect the leftover files, clean them, and do not amend R (index references its hash)',
        details: { release, files: leftover.split('\n').slice(0, 20) },
      });
    }
    return { ...base, commit: release, stagedPaths: plannedPaths };
  } catch (error) {
    if (committed) {
      if (error && typeof error === 'object' && error.details === undefined && release) {
        error.details = { release };
      }
      throw error;
    }
    if (staged) {
      try {
        git.resetPaths(plannedPaths);
      } catch {
        // restoring the files below is the important rollback; index state is reported by `git status`
      }
    }
    restore(root, backupRoot, state);
    throw error;
  } finally {
    fs.rmSync(backupRoot, { recursive: true, force: true });
  }
}

export { buildReleaseIdentity };
